import{c as a,Q as l,j as r,m as e}from"./chunks/framework.rWdQudnF.js";const _=JSON.parse('{"title":"独立构件风格","description":"","frontmatter":{"title":"独立构件风格"},"headers":[],"relativePath":"综合知识/架构设计/独立构件风格.md","filePath":"综合知识/架构设计/独立构件风格.md","lastUpdated":null}'),o={name:"综合知识/架构设计/独立构件风格.md"};function i(n,t,s,d,h,u){return l(),r("div",null,[...t[0]||(t[0]=[e('<blockquote><p>独立构件风格的核心：构件<strong>相对独立</strong>，通过消息传递或事件触发通信，构件间<strong>松耦合</strong>。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 进程通信：独立进程，消息传递</li><li>[ ] 事件驱动（隐式调用）：触发者不知道影响谁</li><li>[ ] C2 风格（亦属独立构件一种）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="进程通信" tabindex="-1">进程通信 <a class="header-anchor" href="#进程通信" aria-label="Permalink to &quot;进程通信&quot;">​</a></h3><ul><li>构件 = 独立的进程</li><li>连接件 = 消息传递</li><li>消息传递方式：点对点、异步/同步、远程过程调用等</li><li>⚠️ <strong>共享内存</strong>不属于消息传递方式</li></ul><h3 id="事件驱动系统-隐式调用-高频考点" tabindex="-1">事件驱动系统（隐式调用）（高频考点） <a class="header-anchor" href="#事件驱动系统-隐式调用-高频考点" aria-label="Permalink to &quot;事件驱动系统（隐式调用）（高频考点）&quot;">​</a></h3><ul><li>构件不直接调用过程，而是<strong>触发或广播</strong>一个或多个事件</li><li>构件中的过程在事件中注册，事件触发时系统<strong>自动调用注册的过程</strong></li><li><strong>触发者不知道哪些构件会被事件影响</strong>（核心特征）</li></ul><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>为软件复用提供强大支持</td><td>构件放弃了对系统计算的控制</td></tr><tr><td>便于构件维护和演化</td><td></td></tr></tbody></table><h3 id="🎯-典型考题" tabindex="-1">🎯 典型考题 <a class="header-anchor" href="#🎯-典型考题" aria-label="Permalink to &quot;🎯 典型考题&quot;">​</a></h3><ul><li><strong>Windows GUI 处理</strong> → 事件驱动风格</li><li><strong>机器人动态响应环境</strong> → 隐式调用</li><li><strong>编程 IDE 中语法高亮/错误提示</strong> → 事件驱动</li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>参见 <a href="./.html">架构师-备考 综合知识-架构设计-架构风格与模式#练习题</a>（Q13, Q30, Q46, Q47, Q48 等）</p>',13)])])}const b=a(o,[["render",i]]);export{_ as __pageData,b as default};
